<?php
declare(strict_types=1);
// Page: ?page=sql — included by index.php inside its try/catch, after the sign-in, CSRF and $page checks.
 require_perm('run_sql'); $schema=current_schema(); $result=null; if($_SERVER['REQUEST_METHOD']==='POST'){ $sql=trim($_POST['sql']??''); $kind=safe_sql_kind($sql); if(in_array($kind,SQL_READONLY_KINDS,true)){ $isCsv=(($_POST['format']??''))==='csv'; $result=run_sql($schema,$sql,$isCsv?SQL_CONSOLE_CSV_MAX_ROWS:SQL_CONSOLE_MAX_ROWS); if($isCsv){ audit('sql_csv_export',$schema,null,null,$sql); header('Content-Type:text/csv'); header('Content-Disposition: attachment; filename="query_export.csv"'); $out=fopen('php://output','w'); $first=true; foreach($result['rows'] as $row){ if($first){fputcsv($out,array_keys($row));$first=false;} fputcsv($out,csv_safe_row($row)); } if($first) fputcsv($out,['(no rows returned)']); exit; } } else { if(is_protected_schema($schema)) throw new RuntimeException($schema.' is read-only in the SQL Console. Use the record forms (Add/Edit/Copy) for production writes.'); $token=make_confirmation('sql',['schema'=>$schema,'sql'=>$sql,'return_to'=>'?page=sql']); redirect('?page=confirm&token='.$token); } if(!empty($_POST['save_name'])) portal_pdo()->prepare('INSERT INTO saved_queries(name,schema_name,sql_text,created_by) VALUES(?,?,?,?)')->execute([$_POST['save_name'],$schema,$sql,user()['username']]); } layout_start('SQL Console'); ?><div class="cardx"><h3>Safe SQL Console</h3><p class="text-muted">DELETE, DROP and TRUNCATE are blocked. Write queries require confirmation. A leading <code>WITH ... AS (...)</code> common table expression is allowed — it's classified by the real statement that follows it.<?php if(is_protected_schema($schema)):?> <strong><?=e($schema)?> is read-only here</strong> — SELECT/SHOW/DESCRIBE/EXPLAIN only; use the record forms for production writes.<?php endif;?></p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><textarea name="sql" class="form-control code" rows="8" placeholder="SELECT * FROM subscription LIMIT 20"><?=e($_POST['sql']??'')?></textarea><div class="row g-2 mt-2"><div class="col-md-6"><input class="form-control" name="save_name" placeholder="Optional name to save this query"></div><div class="col-md-3"><button class="btn btn-primary w-100" name="format" value="preview">Run / Preview</button></div><div class="col-md-3"><button class="btn btn-outline-primary w-100" name="format" value="csv">Download CSV</button></div></div></form></div><?php if($result):?><div class="cardx mt-3"><h3>Result</h3><?php if($result['affected']!==null):?><p>Affected rows: <?=e($result['affected'])?></p><?php else:?><?php if(!empty($result['truncated'])):?><div class="alert alert-warning py-2">Showing the first <?=number_format($result['limit'])?> rows only — add a <code>LIMIT</code> or narrower <code>WHERE</code>, or use Download CSV (up to <?=number_format(SQL_CONSOLE_CSV_MAX_ROWS)?> rows). Queries are stopped after <?=SQL_CONSOLE_TIMEOUT_MS/1000?>s.</div><?php endif;?><div class="table-scroll"><table class="table table-sm"><thead><tr><?php foreach(array_keys($result['rows'][0]??[]) as $h):?><th><?=e($h)?></th><?php endforeach;?></tr></thead><tbody><?php foreach($result['rows'] as $row):?><tr><?php foreach($row as $v):?><td><?=e(mb_strimwidth((string)$v,0,90,'...'))?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php endif;?></div><?php endif; layout_end(); exit;
